import React from 'react';
import cx from 'classnames';
import _T from '../lang';

import {MDCTextField} from '@material/textfield';

import bs from "../styles/styles.module.scss";
import "../styles/styles.scss";
import formStyle from "./form.module.scss";
import './mdc.scss';

type RequestFormProps = { lang: string; handleSubmit: () => void; handleBack: () => void; };
class RequestForm extends React.Component<RequestFormProps> {

    componentDidMount(): void {
        //const textField = new MDCTextField(document.querySelector('.mdc-text-field') as Element);
        [].map.call(document.querySelectorAll('.mdc-text-field'), function(el) {
            return new MDCTextField(el);
        });
    }

    getTextFieldOutlined = (id:string, label:string, mandatory:boolean) => {
        return (
            <div className="mdc-text-field mdc-text-field--outlined" style={{width: "100%"}}>
                <div className={formStyle["form-label-dum"]}/>
                <input type="text" id={id} className="mdc-text-field__input"/>
                {mandatory && <span className={cx(formStyle["form-label-asterisk"])}>*</span>}
                    <div className="mdc-notched-outline">
                        <div className="mdc-notched-outline__leading"/>
                        <div className="mdc-notched-outline__notch">
                            <label htmlFor={id} className="mdc-floating-label">{label}</label>
                        </div>
                        <div className="mdc-notched-outline__trailing"/>
                    </div>
            </div>
        )
    };

    render() {
        let lang = this.props.lang;
        return (
            <form className={formStyle.formBody} id="form-request">
                <div className={bs["form-row"]}>
                    <div className={cx(bs["col-sm-6"], bs["mb-3"])}>
                        {this.getTextFieldOutlined("firstName", _T(lang,"First name"), true)}
                    </div>
                    <div className={cx(bs["col-sm-6"], bs["mb-3"])}>
                        {this.getTextFieldOutlined("lastName", _T(lang,"Last name"), true)}
                    </div>
                </div>
                <div className={bs["mb-3"]} style={{paddingLeft: "10px", paddingRight: "10px"}}>
                    {this.getTextFieldOutlined("email", _T(lang,"Email"), true)}
                </div>
                <hr className={bs["mb-3"]}/>
                <div className={bs["form-row"]}>
                    <div className={cx(bs["col-sm-6"], bs["mb-3"])}>
                        {this.getTextFieldOutlined("asn", _T(lang,"ASN"), true)}
                    </div>
                    <div className={cx(bs["col-sm-6"], bs["mb-3"])}>
                        {this.getTextFieldOutlined("networkName", _T(lang,"Network name"), true)}
                    </div>
                </div>
                <div className={bs["mb-3"]} style={{paddingLeft: "10px", paddingRight: "10px"}}>
                    {this.getTextFieldOutlined("as-set", _T(lang,"AS-SET"), false)}
                </div>
                <div className={cx(bs["form-row"], bs["mb-4"])}>
                    <div className={bs["col-sm-6"]}>
                        <label htmlFor="tunnelLocation">{_T(lang, "Tunnel location")}</label>
                        <select className={cx(bs["form-control"], bs["form-control-lg"])} id="tunnelLocation" defaultValue={_T(lang,"Tokyo")}>
                            <option value="beijing">{_T(lang,"Beijing")}</option>
                            <option value="frankfurt">{_T(lang,"Frankfurt")}</option>
                            <option value="tokyo">{_T(lang,"Tokyo")}</option>
                            <option value="other">{_T(lang,"Other")}</option>
                        </select>
                    </div>
                    <div className={bs["col-sm-6"]}>
                        <label htmlFor="tunnelType">{_T(lang, "Tunnel type")}</label>
                        <select className={cx(bs["form-control"], bs["form-control-lg"])} id="tunnelType" defaultValue="ZeroTier">
                            <option>OpenVPN</option>
                            <option>ZeroTier</option>
                            <option>GRE/SIT</option>
                            <option>Other</option>
                        </select>
                    </div>
                </div>
                <div className={bs["form-row"]} style={{paddingLeft: "20px", paddingRight: "20px"}}>
                    {/*<div className={cx(bs["col-6"], bs["mb-3"])}>*/}
                    {/*    <button className={cx(bs.btn, bs["btn-light"], bs["btn-block"])} onClick={this.props.handleBack}>{_T(lang, "Back")}</button>*/}
                    {/*</div>*/}
                    {/*<div className={cx(bs["col-6"], bs["mb-3"])}>*/}
                        <button className={cx(bs.btn, bs["btn-primary"], bs["btn-block"])} onClick={this.props.handleSubmit} type="button">{_T(lang, "Next")}</button>
                    {/*</div>*/}
                </div>
            </form>
        )
    }
}

export default RequestForm;